  "bt_prop_levier_unite_de_temps_haute": "Subir una temporalidad",
  "bt_prop_levier_seance": "Abrir la sesión a todo el día",
  "bt_prop_levier_risque_par_trade": "Arriesgar menos por operación",
  "bt_prop_levier_pertes_daffilee": "Cortar el día tras N pérdidas",
